<?php
/** @var array<string,mixed> $recollection */
require SMTT_CIF_GESTAO_PATH . 'templates/layout/header.php';
$fmt = static fn($value): string => is_string($value) && $value !== '' ? wp_date('d/m/Y H:i', strtotime($value . ' UTC')) : '—';

$returnToReport = null;
if (isset($_GET['retorno'])) {
    $candidate = wp_validate_redirect((string)wp_unslash($_GET['retorno']), '');
    $reportsPath = wp_parse_url(home_url('/cif/relatorios'), PHP_URL_PATH);
    $candidatePath = $candidate !== '' ? wp_parse_url($candidate, PHP_URL_PATH) : null;
    if (is_string($candidate) && $candidate !== '' && is_string($reportsPath) && $candidatePath === $reportsPath) {
        $returnToReport = $candidate;
    }
}
?>
<section class="cif-page-head"><div><p class="cif-eyebrow">Recolhimento CIF</p><h1><?= esc_html((string)$recollection['motivo_label']) ?></h1><p><strong><?= esc_html((string)$recollection['nome_completo']) ?></strong> · Matrícula <?= esc_html((string)$recollection['matricula']) ?> · <a href="<?= esc_url(home_url('/cif/emissoes/'.rawurlencode((string)$recollection['emissao_uuid']))) ?>"><code><?= esc_html((string)$recollection['codigo_validacao']) ?></code></a></p></div><div class="cif-inline-actions"><?php if ($returnToReport !== null): ?><a class="cif-button cif-button--ghost" href="<?= esc_url($returnToReport) ?>">Voltar ao relatório</a><?php endif; ?><span class="cif-badge"><?= esc_html((string)$recollection['status_label']) ?></span></div></section>
<?php if($notice): ?><div class="cif-alert cif-alert--<?= esc_attr($notice['type']) ?>"><?= esc_html($notice['text']) ?></div><?php endif; ?><?php if($error): ?><div class="cif-alert cif-alert--error"><?= esc_html($error) ?></div><?php endif; ?>
<div class="cif-detail-grid"><section class="cif-panel"><h2>Controle do recolhimento</h2><dl class="cif-definition-list"><div><dt>Fato</dt><dd><?= esc_html($fmt($recollection['fato_em'])) ?></dd></div><div><dt>Solicitado em</dt><dd><?= esc_html($fmt($recollection['recolhimento_solicitado_em'])) ?></dd></div><div><dt>Recolhimento devido</dt><dd><?= esc_html($fmt($recollection['recolhimento_devido_em'])) ?></dd></div><div><dt>Recolhida em</dt><dd><?= esc_html($fmt($recollection['recolhida_em'])) ?></dd></div><div><dt>Inutilização permitida em</dt><dd><?= esc_html($fmt($recollection['inutilizacao_permitida_em'])) ?></dd></div><div><dt>Inutilizada em</dt><dd><?= esc_html($fmt($recollection['inutilizada_em'])) ?></dd></div><div><dt>Referência</dt><dd><?= esc_html((string)($recollection['referencia'] ?: '—')) ?></dd></div></dl></section><section class="cif-panel"><h2>Situação da CIF</h2><dl class="cif-definition-list"><div><dt>Validade</dt><dd><?= esc_html((string)$recollection['status_validade']) ?></dd></div><div><dt>Físico</dt><dd><?= esc_html((string)$recollection['status_fisico']) ?></dd></div><div><dt>Registrado por</dt><dd><?= esc_html((string)$recollection['registrado_por_nome']) ?></dd></div><div><dt>Observações</dt><dd><?= nl2br(esc_html((string)($recollection['observacoes'] ?: '—'))) ?></dd></div></dl></section></div>
<?php if($canRegister && (string)$recollection['status']==='PENDENTE'): ?><section class="cif-section cif-panel"><h2>Concluir diligência de recolhimento</h2><form method="post" action="<?= esc_url(home_url('/cif/recolhimentos/'.rawurlencode((string)$recollection['uuid']).'/recolher')) ?>" class="cif-form"><h3>Documento devolvido</h3><?php smtt_cif_nonce_field('smtt_cif_recollection_collect_'.(string)$recollection['uuid'],'smtt_cif_nonce'); ?><label class="cif-field"><span>Referência</span><input name="referencia" maxlength="200"></label><label class="cif-field"><span>Observações</span><textarea name="observacoes" maxlength="2000"></textarea></label><button class="cif-button cif-button--primary">Confirmar recolhimento físico</button></form>
<?php if((string)$recollection['motivo_codigo']==='FALECIMENTO'): ?><hr class="cif-divider"><form method="post" action="<?= esc_url(home_url('/cif/recolhimentos/'.rawurlencode((string)$recollection['uuid']).'/nao-recolhido')) ?>" class="cif-form"><h3>Documento não devolvido</h3><?php smtt_cif_nonce_field('smtt_cif_recollection_not_collected_'.(string)$recollection['uuid'],'smtt_cif_nonce'); ?><label class="cif-field"><span>Justificativa</span><textarea name="justificativa" minlength="10" maxlength="2000" required></textarea><small>Disponível após o prazo de 60 dias.</small></label><button class="cif-button cif-button--secondary">Registrar impossibilidade de devolução</button></form><?php endif; ?></section><?php endif; ?>
<?php if($canInvalidate && (string)$recollection['status']==='RECOLHIDA'): ?><section class="cif-section cif-panel"><h2>Inutilização física</h2><p>A operação somente será aceita quando a data de inutilização permitida tiver sido atingida.</p><form method="post" action="<?= esc_url(home_url('/cif/recolhimentos/'.rawurlencode((string)$recollection['uuid']).'/inutilizar')) ?>" class="cif-form"><?php smtt_cif_nonce_field('smtt_cif_recollection_invalidate_'.(string)$recollection['uuid'],'smtt_cif_nonce'); ?><label class="cif-field"><span>Observações</span><textarea name="observacoes" maxlength="2000"></textarea></label><button class="cif-button cif-button--primary">Registrar inutilização</button></form></section><?php endif; ?>
<section class="cif-section"><a class="cif-button cif-button--ghost" href="<?= esc_url($returnToReport ?? (home_url('/cif/emissoes/'.rawurlencode((string)$recollection['emissao_uuid'])) . '#historico-cif')) ?>"><?= $returnToReport !== null ? 'Voltar ao relatório' : 'Voltar à emissão' ?></a></section>
<?php require SMTT_CIF_GESTAO_PATH . 'templates/layout/footer.php'; ?>
